type SkillFile = { id: string; path: string; type: string; content: string };
type SkillStep = { id: string; name: string; type: string; dependsOn: string[]; config: Record<string, unknown> | string; onError: string; timeoutMs: number; retries: number; enabled: boolean };
type Assertion = { id: string; type: string; path: string; value: unknown; pass?: boolean; actual?: unknown; message?: string };
type SkillTest = { id: string; name: string; input: Record<string, unknown> | string; tags: string[]; assertions: Assertion[] };
type TraceItem = { order: number; stepId: string; name: string; type: string; status: string; elapsedMs: number; message: string };
type TestResult = { testId: string; name: string; passed: boolean; assertions: Assertion[]; output: Record<string, unknown>; trace: TraceItem[]; error: string; elapsedMs: number; tags: string[]; baseline: boolean };
type Evaluation = { id: string; createdAt: string; results: TestResult[]; baselines: TestResult[]; total: number; passed: number; failed: number; passRate: number; baselinePassRate: number; uplift: number; assertionTotal: number; assertionPassed: number; assertionRate: number; p50Ms: number; p95Ms: number; stepCoverage: number };
type SkillRelease = { id: string; version: string; channel: string; notes: string; createdAt: string; evaluation: Evaluation; gate: { pass: boolean; blockers: string[]; warnings: string[] }; snapshot: Partial<SkillDefinition> };
type SkillDefinition = {
  id: string; name: string; slug: string; version: string; status: string; channel: string; description: string;
  metadata: { name: string; description: string; license: string; compatibility: string; allowedTools: string; owner: string; tags: string };
  instructions: string; contract: { inputSchema: Record<string, unknown>; outputSchema: Record<string, unknown> };
  steps: SkillStep[]; tests: SkillTest[]; files: SkillFile[];
  policy: { minimumPassRate: number; minimumAssertionRate: number };
  provenance: { source: string; maintainer: string; upstream: string; licenseReview: string; signatureStatus: string; reviewedAt: string };
  releaseNotes: string; playgroundInput: Record<string, unknown> | string;
  runs: Array<{ id: string; createdAt: string; input: unknown; status: string; output: Record<string, unknown>; trace: TraceItem[]; error: string }>;
  evaluations: Evaluation[]; releases: SkillRelease[]; createdAt: string; updatedAt: string;
};
type SkillEvolutionResult = {
  schema: 'skyview-skill-evolution-results'; version: number; stage: string; skill: SkillDefinition;
  registry: Array<{ id: string; name: string; slug: string; version: string; channel: string; status: string; maturity: number; passRate: number }>;
  maturity: { total: number; scores: Record<string, number>; metadata: { valid: boolean; issues: Array<{ severity: string; message: string }> }; inputContract: { valid: boolean; issues: Array<{ severity: string; message: string }> }; outputContract: { valid: boolean; issues: Array<{ severity: string; message: string }> }; workflow: { valid: boolean; issues: Array<{ severity: string; message: string }>; order: string[] } };
  evaluation: Evaluation;
  latestRun: { id: string; createdAt: string; input: unknown; status: string; output: Record<string, unknown>; trace: TraceItem[]; error: string } | null;
  security: { findings: Array<{ severity: string; code: string; message: string; file: string }>; counts: Record<string, number>; pass: boolean };
  releaseGate: { pass: boolean; blockers: string[]; warnings: string[] };
  qualityChecks: Array<{ label: string; passed: boolean }>;
  runtime: { compute: string; orchestration: string; arbitraryCodeExecution: boolean; networkAccess: boolean; packageImportIsolation: boolean; signatureVerificationConfigured: boolean };
  exports: { skillMarkdown: string; evaluationJson: string; benchmarkMarkdown: string; skillCardMarkdown: string; manifestJson: string; registryJson: string; packageBase64: string };
};

