  const markdown = `---\nname: "research-evidence-extractor"\ndescription: "当用户需要从研究材料中提取可追溯证据句、生成结构化摘要并进入人工复核时使用。"\nlicense: "SkyViewLab internal review license"\ncompatibility: "Agent Skills specification"\nallowed-tools: "Read Grep"\n---\n\n${instructions}\n`;
