function createBenchmarkResult(): SkillEvolutionResult {
  const skill = sampleSkill();
  const trace = skill.steps.map((step, index) => ({ order: index + 1, stepId: step.id, name: step.name, type: step.type, status: 'completed', elapsedMs: 0.04 + index * 0.01, message: '步骤完成' }));
  const output = { summary: '城市内涝遥感分析：降雨后影像中低洼区域水体指数明显升高。', findings: ['降雨后影像中低洼区域水体指数明显升高。', '道路积水范围与现场巡查记录基本一致。', '该结果仍需结合云量和地面观测复核。'], reviewRequired: true };
  const results = skill.tests.map((item, index) => ({ testId: item.id, name: item.name, passed: true, assertions: item.assertions.map((assertion) => ({ ...assertion, pass: true, actual: assertion.path === 'findings' ? output.findings : assertion.path === 'reviewRequired' ? true : assertion.value, message: '通过' })), output, trace, error: index === 3 ? '缺少必填字段：title' : '', elapsedMs: 0.16 + index * 0.03, tags: item.tags, baseline: false }));
  const baselines = results.map((item) => ({ ...item, passed: false, assertions: item.assertions.map((assertion) => ({ ...assertion, pass: false })), trace: [], baseline: true }));
  const evaluation: Evaluation = { id: 'eval-benchmark', createdAt: '2026-09-09T00:00:00Z', results, baselines, total: 4, passed: 4, failed: 0, passRate: 1, baselinePassRate: 0, uplift: 1, assertionTotal: 8, assertionPassed: 8, assertionRate: 1, p50Ms: 0.21, p95Ms: 0.25, stepCoverage: 1 };
  const latestRun = { id: 'run-benchmark', createdAt: '2026-09-09T00:00:00Z', input: skill.playgroundInput, status: 'success', output, trace, error: '' };
  skill.runs = [latestRun]; skill.evaluations = [evaluation];
  const scores = { specification: 100, contract: 100, workflow: 100, evaluation: 100, security: 100, observability: 100 };
  const releaseGate = { pass: true, blockers: [] as string[], warnings: [] as string[] };
  return { schema: 'skyview-skill-evolution-results', version: 2, stage: 'run-all', skill, registry: [{ id: skill.id, name: skill.name, slug: skill.slug, version: skill.version, channel: skill.channel, status: skill.status, maturity: 100, passRate: 1 }], maturity: { total: 100, scores, metadata: { valid: true, issues: [] }, inputContract: { valid: true, issues: [] }, outputContract: { valid: true, issues: [] }, workflow: { valid: true, issues: [], order: skill.steps.map((item) => item.id) } }, evaluation, latestRun, security: { findings: [], counts: { critical: 0, high: 0, medium: 0, low: 0 }, pass: true }, releaseGate, qualityChecks: ['元数据与渐进披露符合规范', '输入与输出契约有效', 'DAG 无循环或断裂依赖', '用例与断言达到发布门槛', '步骤覆盖率达到 100%', '不存在严重或高风险发现'].map((label) => ({ label, passed: true })), runtime: { compute: 'Python 固定安全步骤引擎', orchestration: 'Go 项目、版本、作业与审计', arbitraryCodeExecution: false, networkAccess: false, packageImportIsolation: true, signatureVerificationConfigured: false }, exports: { skillMarkdown: skill.files[0].content, evaluationJson: JSON.stringify({ schema: 'skyview-skill-evals', version: 2, tests: skill.tests, evaluation }, null, 2), benchmarkMarkdown: '# BENCHMARK\n\n- Cases: 4\n- Pass rate: 100.0%\n- Step coverage: 100.0%\n', skillCardMarkdown: `# ${skill.name}\n\n${skill.metadata.description}\n`, manifestJson: JSON.stringify({ schema: 'skyview-agent-skill-package', schemaVersion: 2, name: skill.slug, version: skill.version }, null, 2), registryJson: JSON.stringify({ schema: 'skyview-skill-registry', schemaVersion: 2, skills: [skill] }, null, 2), packageBase64: '' } };
}

function percent(value: number) { return `${(value * 100).toFixed(value === 1 ? 0 : 1)}%`; }
function formatTime(value: string) { return new Intl.DateTimeFormat('zh-CN', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(value)); }
function downloadText(content: string, fileName: string, type = 'text/plain;charset=utf-8') { const url = URL.createObjectURL(new Blob(['\ufeff', content], { type })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = fileName; document.body.appendChild(anchor); anchor.click(); anchor.remove(); URL.revokeObjectURL(url); }
function downloadBase64(content: string, fileName: string) { const bytes = Uint8Array.from(atob(content), (character) => character.charCodeAt(0)); const url = URL.createObjectURL(new Blob([bytes], { type: 'application/zip' })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = fileName; document.body.appendChild(anchor); anchor.click(); anchor.remove(); URL.revokeObjectURL(url); }
async function fileBase64(file: File) { const bytes = new Uint8Array(await file.arrayBuffer()); let binary = ''; for (let offset = 0; offset < bytes.length; offset += 0x8000) binary += String.fromCharCode(...bytes.subarray(offset, offset + 0x8000)); return btoa(binary); }

function MaturityRadar({ result }: { result: SkillEvolutionResult }) {
  const dimensions = Object.entries(result.maturity.scores); const center = 120; const radius = 82;
  const polygon = dimensions.map(([, score], index) => { const angle = -Math.PI / 2 + index * Math.PI * 2 / dimensions.length; return `${center + Math.cos(angle) * radius * score / 100},${center + Math.sin(angle) * radius * score / 100}`; }).join(' ');
  const labels: Record<string, string> = { specification: '规范', contract: '契约', workflow: '流程', evaluation: '评测', security: '安全', observability: '证据' };
  return <svg className="skillx-radar" viewBox="0 0 240 240" aria-label="六维能力成熟度雷达图"><title>六维能力成熟度雷达图</title>{[.25, .5, .75, 1].map((scale) => <polygon key={scale} points={dimensions.map((_, index) => { const angle = -Math.PI / 2 + index * Math.PI * 2 / dimensions.length; return `${center + Math.cos(angle) * radius * scale},${center + Math.sin(angle) * radius * scale}`; }).join(' ')} />)}{dimensions.map(([id], index) => { const angle = -Math.PI / 2 + index * Math.PI * 2 / dimensions.length; return <g key={id}><line x1={center} y1={center} x2={center + Math.cos(angle) * radius} y2={center + Math.sin(angle) * radius} /><text x={center + Math.cos(angle) * 105} y={center + Math.sin(angle) * 101}>{labels[id]}</text></g>; })}<polygon className="value" points={polygon} /><circle cx={center} cy={center} r="29" /><text className="score" x={center} y={center + 6}>{result.maturity.total}</text></svg>;
}

export function SkillEvolutionWorkbench({ executionAllowed = true }: { executionAllowed?: boolean }) {
  const [selectedView, setSelectedView] = useState<(typeof views)[number][0]>('overview');
  const [result, setResult] = useState<SkillEvolutionResult>(() => createBenchmarkResult());
  const [projects, setProjects] = useState<WorkbenchProject[]>([]); const [projectId, setProjectId] = useState('');
  const [projectTitle, setProjectTitle] = useState('科研证据提取器能力项目');
  const [running, setRunning] = useState(false); const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState('完整确定性基准、评测结果与运行追踪已载入。'); const [error, setError] = useState('');
  const [selectedFileId, setSelectedFileId] = useState('F1'); const [selectedReleaseId, setSelectedReleaseId] = useState('');
  const [releaseLevel, setReleaseLevel] = useState('patch'); const [releaseChannel, setReleaseChannel] = useState('canary');
  const packageInput = useRef<HTMLInputElement>(null); const datasetInput = useRef<HTMLInputElement>(null);

  useEffect(() => { let active = true; toolApi.listProjects('skill-evolution').then((items) => { if (!active) return; setProjects(items); const project = items[0]; const saved = project?.state.skillEvolution as { result?: SkillEvolutionResult } | undefined; if (project && saved?.result?.schema === 'skyview-skill-evolution-results') { setProjectId(project.id); setProjectTitle(project.title); setResult(saved.result); setMessage('已打开最近的 Skill 能力项目。'); } }).catch(() => undefined); return () => { active = false; }; }, []);
  const projectState = (nextResult: SkillEvolutionResult = result) => ({ skillEvolution: { result: nextResult } });
  const ensureProject = async () => { const existing = projects.find((project) => project.id === projectId); if (existing) return existing; const created = await toolApi.createProject('skill-evolution', projectTitle, projectState()); setProjects((items) => [created, ...items]); setProjectId(created.id); return created; };
  const storeResult = async (project: WorkbenchProject, output: SkillEvolutionResult) => { setResult(output); setSelectedFileId(output.skill.files[0]?.id ?? ''); const saved = await toolApi.updateProject(project.id, projectTitle, projectState(output)); setProjects((items) => [saved, ...items.filter((item) => item.id !== saved.id)]); };
  const execute = async (action: string, extra: Record<string, unknown> = {}, skillOverride?: SkillDefinition) => {
    if (!executionAllowed) return; setRunning(true); setError(''); setMessage('Go 已登记作业，Python 正在执行安全步骤与证据计算…');
    try { const project = await ensureProject(); const input = action === 'import-package' ? extra : { skill: skillOverride ?? result.skill, ...extra }; const created = await toolApi.createJob(project.id, 'skill-evolution', action, input, crypto.randomUUID()); const job = await waitForJob(created.job.id); if (!job) throw new Error('作业仍在后台运行，请稍后重新打开项目。'); if (job.status === 'failed') throw new Error(job.error || '计算失败。'); if (job.status === 'canceled') throw new Error('计算已取消。'); const output = job.result as SkillEvolutionResult; if (output.schema !== 'skyview-skill-evolution-results') throw new Error('服务端返回了不兼容的结果。'); await storeResult(project, output); if (action === 'publish') { setSelectedReleaseId(output.skill.releases[0]?.id ?? ''); setSelectedView('releases'); } setMessage(action === 'run-all' ? '八个工作区已完成联动校验，评测和交付包均已更新。' : action === 'publish' ? `版本 ${output.skill.version} 已生成不可变发布快照。` : '当前能力证据已更新。'); }
    catch (caught) { setError(caught instanceof ApiError || caught instanceof Error ? caught.message : '操作失败。'); setMessage(''); } finally { setRunning(false); }
  };
  const saveProject = async () => { setSaving(true); setError(''); try { const existing = projects.find((project) => project.id === projectId); const saved = existing ? await toolApi.updateProject(existing.id, projectTitle, projectState()) : await toolApi.createProject('skill-evolution', projectTitle, projectState()); setProjects((items) => [saved, ...items.filter((item) => item.id !== saved.id)]); setProjectId(saved.id); setMessage('Skill 项目已保存。'); } catch (caught) { setError(caught instanceof Error ? caught.message : '保存失败。'); } finally { setSaving(false); } };
  const createVersion = async () => { setSaving(true); setError(''); try { const project = await ensureProject(); await toolApi.createVersion(project.id, `Skill ${result.skill.version} · ${new Date().toLocaleString('zh-CN')}`, projectState()); setMessage('已创建不可变项目版本。'); } catch (caught) { setError(caught instanceof Error ? caught.message : '创建版本失败。'); } finally { setSaving(false); } };
  const selectProject = (id: string) => { const project = projects.find((item) => item.id === id); setProjectId(id); if (!project) { setResult(createBenchmarkResult()); setProjectTitle('科研证据提取器能力项目'); return; } const saved = project.state.skillEvolution as { result?: SkillEvolutionResult } | undefined; if (saved?.result?.schema === 'skyview-skill-evolution-results') { setResult(saved.result); setProjectTitle(project.title); } };
  const updateSkill = (change: (skill: SkillDefinition) => void) => setResult((current) => { const next = structuredClone(current); change(next.skill); next.skill.updatedAt = new Date().toISOString(); return next; });
  const updateMetadata = (key: keyof SkillDefinition['metadata'], value: string) => updateSkill((skill) => { skill.metadata[key] = value; if (key === 'name') skill.slug = value; });
  const mutateStep = (id: string, change: (step: SkillStep) => void) => updateSkill((skill) => { const step = skill.steps.find((item) => item.id === id); if (step) change(step); });
  const mutateTest = (id: string, change: (test: SkillTest) => void) => updateSkill((skill) => { const test = skill.tests.find((item) => item.id === id); if (test) change(test); });
  const selectedFile = result.skill.files.find((item) => item.id === selectedFileId) ?? result.skill.files[0];
  const selectedRelease = result.skill.releases.find((item) => item.id === selectedReleaseId) ?? result.skill.releases[0];
  const dimensionLabels: Record<string, string> = { specification: '规范', contract: '契约', workflow: '流程', evaluation: '评测', security: '安全', observability: '证据' };
  const topologicalSteps = useMemo(() => result.maturity.workflow.order.map((id) => result.skill.steps.find((step) => step.id === id)).filter(Boolean) as SkillStep[], [result.maturity.workflow.order, result.skill.steps]);

  const addStep = () => updateSkill((skill) => { const id = `step-${Date.now()}`; skill.steps.push({ id, name: '新步骤', type: 'assign', dependsOn: skill.steps.length ? [skill.steps.at(-1)!.id] : [], config: { targetPath: 'output.value', value: '' }, onError: 'stop', timeoutMs: 1000, retries: 0, enabled: true }); });
  const moveStep = (id: string, offset: number) => updateSkill((skill) => { const index = skill.steps.findIndex((item) => item.id === id); const target = index + offset; if (index >= 0 && target >= 0 && target < skill.steps.length) [skill.steps[index], skill.steps[target]] = [skill.steps[target], skill.steps[index]]; });
  const cloneStep = (id: string) => updateSkill((skill) => { const source = skill.steps.find((item) => item.id === id); if (!source) return; const copy = structuredClone(source); copy.id = `${source.id}-copy-${Date.now().toString().slice(-4)}`; copy.name += ' 副本'; skill.steps.splice(skill.steps.indexOf(source) + 1, 0, copy); });
  const addTest = () => updateSkill((skill) => skill.tests.push({ id: `test-${Date.now()}`, name: '新测试用例', input: {}, tags: ['draft'], assertions: [{ id: `assert-${Date.now()}`, type: 'path-exists', path: 'summary', value: '' }] }));
  const newSkill = (copy: boolean) => { const next = createBenchmarkResult(); const suffix = Date.now().toString().slice(-5); next.skill.id = `skill-${suffix}`; next.skill.name = copy ? `${result.skill.name} 副本` : '新的研究 Skill'; next.skill.slug = copy ? `${result.skill.slug}-copy-${suffix}` : `research-skill-${suffix}`; next.skill.metadata.name = next.skill.slug; next.skill.version = '0.1.0'; next.skill.status = 'draft'; next.skill.channel = 'draft'; next.skill.runs = []; next.skill.evaluations = []; next.skill.releases = []; next.registry[0] = { ...next.registry[0], id: next.skill.id, name: next.skill.name, slug: next.skill.slug, version: next.skill.version, channel: 'draft', status: 'draft' }; setResult(next); setProjectId(''); setProjectTitle(`${next.skill.name}能力项目`); setSelectedView('spec'); setMessage(copy ? '已创建独立副本，请核对规范后保存。' : '已建立新的 Skill 草案。'); };
  const importPackage = async (file?: File) => { if (!file) return; try { if (file.name.toLowerCase().endsWith('.json')) { const value = JSON.parse(await file.text()) as SkillEvolutionResult | { skills?: SkillDefinition[] }; if ('schema' in value && value.schema === 'skyview-skill-evolution-results') setResult(value); else if ('skills' in value && value.skills?.[0]) await execute('run-all', {}, value.skills[0]); else throw new Error('JSON 中未找到兼容的 Skill 项目或注册表。'); setMessage(`已导入 ${file.name}。`); } else await execute('import-package', { packageBase64: await fileBase64(file), fileName: file.name }); } catch (caught) { setError(caught instanceof Error ? caught.message : '导入失败。'); } finally { if (packageInput.current) packageInput.current.value = ''; } };
  const importDataset = async (file?: File) => { if (!file) return; await execute('import-dataset', { dataset: await file.text(), fileName: file.name }); if (datasetInput.current) datasetInput.current.value = ''; };
  const restoreRelease = () => { if (!selectedRelease) return; const restored = { ...structuredClone(result.skill), ...structuredClone(selectedRelease.snapshot), id: result.skill.id, version: result.skill.version, channel: 'draft', status: 'draft', releases: result.skill.releases, runs: result.skill.runs, evaluations: result.skill.evaluations } as SkillDefinition; void execute('run-all', {}, restored); };

  return <section className="skillx-workbench">
    <header className="skillx-commandbar">
      <div className="skillx-project"><FolderOpen /><NativeSelect aria-label="选择 Skill 项目" value={projectId} onChange={(event) => selectProject(event.target.value)}><NativeSelectOption value="">未保存项目</NativeSelectOption>{projects.map((project) => <NativeSelectOption key={project.id} value={project.id}>{project.title}</NativeSelectOption>)}</NativeSelect><Input aria-label="项目名称" value={projectTitle} onChange={(event) => setProjectTitle(event.target.value)} /><span><ShieldCheck />{result.skill.channel === 'draft' ? '草案通道' : result.skill.channel}</span></div>
      <div className="skillx-actions"><Button size="sm" variant="outline" onClick={() => newSkill(false)} disabled={running}><Plus />新建</Button><Button size="sm" variant="outline" onClick={() => newSkill(true)} disabled={running}><Copy />复制</Button><Button size="sm" variant="outline" onClick={() => void saveProject()} disabled={saving || running}>{saving ? <LoaderCircle className="spin" /> : <Save />}保存</Button><Button size="sm" variant="outline" onClick={() => void createVersion()} disabled={saving || running}><Archive />创建版本</Button><input ref={packageInput} hidden type="file" accept=".zip,.json,application/zip,application/json" onChange={(event) => void importPackage(event.target.files?.[0])} /><Button size="sm" variant="outline" onClick={() => packageInput.current?.click()} disabled={running}><FileUp />导入</Button><Button size="sm" onClick={() => void execute('run-all')} disabled={running}>{running ? <LoaderCircle className="spin" /> : <Play />}执行完整流程</Button></div>
    </header>
    <section className="skillx-kpis" aria-label="Skill 能力摘要">
      <article><Boxes /><span>能力成熟度</span><strong>{result.maturity.total}</strong><small>/100</small></article>
      <article><TestTube2 /><span>用例通过率</span><strong>{percent(result.evaluation.passRate)}</strong><small>{result.evaluation.passed}/{result.evaluation.total}</small></article>
      <article><CheckCircle2 /><span>断言通过率</span><strong>{percent(result.evaluation.assertionRate)}</strong><small>{result.evaluation.assertionPassed}/{result.evaluation.assertionTotal}</small></article>
      <article><Network /><span>步骤覆盖率</span><strong>{percent(result.evaluation.stepCoverage)}</strong><small>{result.skill.steps.length} 个步骤</small></article>
      <article><ScanSearch /><span>高风险发现</span><strong>{(result.security.counts.critical ?? 0) + (result.security.counts.high ?? 0)}</strong><small>{result.skill.files.length} 个文件</small></article>
      <article><FileArchive /><span>发布门禁</span><strong>{result.releaseGate.pass ? '通过' : '阻断'}</strong><small>{result.releaseGate.blockers.length} 项阻断</small></article>
    </section>
    <nav className="skillx-tabs" aria-label="Skill 进化工作区">{views.map(([id, label], index) => <button key={id} className={selectedView === id ? 'active' : ''} onClick={() => setSelectedView(id)}><b>{String(index + 1).padStart(2, '0')}</b><span>{label}</span></button>)}</nav>
    {(message || error) && <div className={`skillx-status ${error ? 'error' : ''}`}>{error || message}</div>}
    <main className="skillx-main" data-view={selectedView}>
      {selectedView === 'overview' && <div className="skillx-view skillx-overview">
        <section className="skillx-surface skillx-maturity"><header><span>能力成熟度</span><strong>六维证据模型</strong></header><MaturityRadar result={result} /><div>{Object.entries(result.maturity.scores).map(([id, score]) => <p key={id}><span>{dimensionLabels[id]}</span><i><b style={{ width: `${score}%` }} /></i><strong>{score}</strong></p>)}</div></section>
        <section className="skillx-surface skillx-gate"><header><span>发布门禁</span><strong>{result.releaseGate.pass ? '全部条件已满足' : `${result.releaseGate.blockers.length} 项待处理`}</strong></header><div className="skillx-checks">{result.qualityChecks.map((item) => <p key={item.label} className={item.passed ? 'pass' : 'warn'}>{item.passed ? <CheckCircle2 /> : <CircleAlert />}<span>{item.label}</span></p>)}</div></section>
        <section className="skillx-surface skillx-registry"><header><span>能力注册表</span><strong>{result.registry.length} 个 Skill</strong><Button size="sm" variant="outline" onClick={() => downloadText(result.exports.registryJson, 'skyview-skill-registry.json', 'application/json;charset=utf-8')}><Download />导出注册表</Button></header><div>{result.registry.map((item) => <article key={item.id}><span>{item.channel === 'draft' ? '草案' : item.channel}</span><strong>{item.name}</strong><small>{item.slug} · v{item.version}</small><p><b>{item.maturity} 分</b><em>{percent(item.passRate)}</em></p></article>)}</div></section>
        <section className="skillx-surface skillx-loop"><header><span>进化闭环</span><strong>证据驱动的五阶段链路</strong></header><div>{['定义规范与契约', '编排安全步骤', '构建测试数据集', '评测对照与回归', '门禁发布与回滚'].map((label, index) => <button key={label} onClick={() => setSelectedView((['spec', 'workflow', 'tests', 'evaluation', 'releases'] as const)[index])}><b>{String(index + 1).padStart(2, '0')}</b><span>{label}</span><small>{index < 3 ? '已配置' : '证据已生成'}</small></button>)}</div></section>
      </div>}
      {selectedView === 'spec' && <div className="skillx-view skillx-spec">
        <section className="skillx-surface skillx-metadata"><header><span>规范元数据</span><strong>Agent Skills 渐进披露</strong><em className={result.maturity.metadata.valid ? 'pass' : 'warn'}>{result.maturity.metadata.valid ? '规范通过' : '需要修正'}</em></header><div className="skillx-token-rail"><article><b>层级 1</b><strong>{Math.ceil((result.skill.metadata.name.length + result.skill.metadata.description.length) / 3)}</strong><span>名称与激活描述</span></article><article><b>层级 2</b><strong>{Math.ceil(result.skill.instructions.length / 3)}</strong><span>完整指令</span></article><article><b>层级 3</b><strong>{Math.ceil(result.skill.files.slice(1).reduce((sum, item) => sum + item.content.length, 0) / 3)}</strong><span>按需资源</span></article></div><div className="skillx-form"><div className="skillx-field"><span>工作台显示名</span><Input aria-label="工作台显示名" value={result.skill.name} onChange={(event) => updateSkill((skill) => { skill.name = event.target.value; })} /></div><div className="skillx-field"><span>语义版本</span><Input aria-label="语义版本" value={result.skill.version} onChange={(event) => updateSkill((skill) => { skill.version = event.target.value; })} /></div><div className="skillx-field"><span>规范名称</span><Input aria-label="规范名称" value={result.skill.metadata.name} onChange={(event) => updateMetadata('name', event.target.value)} /></div><div className="skillx-field"><span>负责人</span><Input aria-label="负责人" value={result.skill.metadata.owner} onChange={(event) => updateMetadata('owner', event.target.value)} /></div><label className="wide"><span>激活描述</span><textarea value={result.skill.metadata.description} onChange={(event) => updateMetadata('description', event.target.value)} /></label><div className="skillx-field"><span>许可证</span><Input aria-label="许可证" value={result.skill.metadata.license} onChange={(event) => updateMetadata('license', event.target.value)} /></div><div className="skillx-field"><span>允许工具</span><Input aria-label="允许工具" value={result.skill.metadata.allowedTools} onChange={(event) => updateMetadata('allowedTools', event.target.value)} /></div><label className="wide"><span>SKILL.md 指令正文</span><textarea className="code" value={result.skill.instructions} onChange={(event) => updateSkill((skill) => { skill.instructions = event.target.value; })} /></label></div></section>
        <section className="skillx-surface skillx-contract"><header><span>输入契约</span><strong>JSON Schema</strong><em className={result.maturity.inputContract.valid ? 'pass' : 'warn'}>{result.maturity.inputContract.valid ? '有效' : '无效'}</em></header><textarea className="code" defaultValue={JSON.stringify(result.skill.contract.inputSchema, null, 2)} onBlur={(event) => { try { const parsed = JSON.parse(event.target.value) as Record<string, unknown>; updateSkill((skill) => { skill.contract.inputSchema = parsed; }); setError(''); } catch { setError('输入契约不是有效 JSON。'); } }} /></section>
        <section className="skillx-surface skillx-contract"><header><span>输出契约</span><strong>JSON Schema</strong><em className={result.maturity.outputContract.valid ? 'pass' : 'warn'}>{result.maturity.outputContract.valid ? '有效' : '无效'}</em></header><textarea className="code" defaultValue={JSON.stringify(result.skill.contract.outputSchema, null, 2)} onBlur={(event) => { try { const parsed = JSON.parse(event.target.value) as Record<string, unknown>; updateSkill((skill) => { skill.contract.outputSchema = parsed; }); setError(''); } catch { setError('输出契约不是有效 JSON。'); } }} /></section>
        <section className="skillx-surface skillx-files"><header><span>资源文件树</span><strong>脚本只作文本审查</strong><div><Button size="sm" variant="outline" onClick={() => { const path = window.prompt('输入安全的相对路径', 'references/README.md'); if (!path) return; updateSkill((skill) => { const file = { id: `file-${Date.now()}`, path, type: path.startsWith('scripts/') ? 'script-text-only' : 'reference', content: '' }; skill.files.push(file); setSelectedFileId(file.id); }); }}><Plus />添加</Button><Button size="sm" variant="outline" disabled={!selectedFile || selectedFile.path === 'SKILL.md'} onClick={() => { const path = window.prompt('输入新的相对路径', selectedFile?.path); if (path) updateSkill((skill) => { const file = skill.files.find((item) => item.id === selectedFile?.id); if (file) file.path = path; }); }}>重命名</Button><Button size="sm" variant="outline" disabled={!selectedFile || selectedFile.path === 'SKILL.md'} onClick={() => updateSkill((skill) => { skill.files = skill.files.filter((item) => item.id !== selectedFile?.id); setSelectedFileId(skill.files[0]?.id ?? ''); })}><Trash2 />删除</Button></div></header><div className="skillx-file-layout"><aside>{result.skill.files.map((file) => <button key={file.id} className={selectedFile?.id === file.id ? 'active' : ''} onClick={() => setSelectedFileId(file.id)}><FileCode2 /><span><strong>{file.path}</strong><small>{file.type} · {file.content.length.toLocaleString('zh-CN')} 字符</small></span></button>)}</aside>{selectedFile ? <label><span>{selectedFile.path}{selectedFile.type === 'script-text-only' ? ' · 不执行' : ''}</span><textarea className="code" value={selectedFile.content} readOnly={selectedFile.path === 'SKILL.md'} onChange={(event) => updateSkill((skill) => { const file = skill.files.find((item) => item.id === selectedFile.id); if (file) file.content = event.target.value; })} /></label> : <p>暂无资源文件</p>}</div></section>
      </div>}
      {selectedView === 'workflow' && <div className="skillx-view skillx-workflow">
        <section className="skillx-surface skillx-dag"><header><span>安全流程图</span><strong>{result.maturity.workflow.valid ? '依赖关系有效' : '存在流程问题'}</strong><div><Button size="sm" variant="outline" onClick={addStep}><Plus />添加步骤</Button><Button size="sm" onClick={() => void execute('run')} disabled={running}><Play />试运行</Button></div></header><div className="skillx-dag-flow">{topologicalSteps.map((step, index) => <article key={step.id}><b>{String(index + 1).padStart(2, '0')}</b><GitBranch /><strong>{step.name}</strong><span>{stepTypeLabel(step.type)}</span>{index < topologicalSteps.length - 1 && <i>→</i>}</article>)}</div></section>
        <section className="skillx-step-grid">{result.skill.steps.map((step, index) => <article key={step.id} className={`skillx-surface ${step.enabled ? '' : 'disabled'}`}><header><b>{String(index + 1).padStart(2, '0')}</b><div><Input aria-label="步骤名称" value={step.name} onChange={(event) => mutateStep(step.id, (item) => { item.name = event.target.value; })} /><small>{step.id}</small></div><label><input type="checkbox" checked={step.enabled} onChange={(event) => mutateStep(step.id, (item) => { item.enabled = event.target.checked; })} />启用</label></header><div><div className="skillx-field"><span>步骤类型</span><NativeSelect aria-label="步骤类型" value={step.type} onChange={(event) => mutateStep(step.id, (item) => { item.type = event.target.value; })}>{stepTypes.map(([type, label]) => <NativeSelectOption key={type} value={type}>{label}</NativeSelectOption>)}</NativeSelect></div><div className="skillx-field"><span>依赖步骤</span><Input aria-label="依赖步骤" value={step.dependsOn.join(',')} onChange={(event) => mutateStep(step.id, (item) => { item.dependsOn = event.target.value.split(',').map((value) => value.trim()).filter(Boolean); })} /></div><label className="wide"><span>配置 JSON</span><textarea className="code" defaultValue={JSON.stringify(step.config, null, 2)} onBlur={(event) => { try { const parsed = JSON.parse(event.target.value) as Record<string, unknown>; mutateStep(step.id, (item) => { item.config = parsed; }); } catch { setError(`步骤 ${step.name} 的配置不是有效 JSON。`); } }} /></label></div><footer><button aria-label={`上移 ${step.name}`} disabled={index === 0} onClick={() => moveStep(step.id, -1)}><ChevronUp /></button><button aria-label={`下移 ${step.name}`} disabled={index === result.skill.steps.length - 1} onClick={() => moveStep(step.id, 1)}><ChevronDown /></button><button onClick={() => cloneStep(step.id)}><Copy />复制</button><button className="danger" onClick={() => updateSkill((skill) => { skill.steps = skill.steps.filter((item) => item.id !== step.id); skill.steps.forEach((item) => { item.dependsOn = item.dependsOn.filter((dependency) => dependency !== step.id); }); })}><Trash2 />删除</button></footer></article>)}</section>
      </div>}
      {selectedView === 'tests' && <div className="skillx-view skillx-tests">
        <section className="skillx-surface skillx-test-summary"><header><span>声明式测试数据集</span><strong>核心、边界、负向与安全场景</strong><div><input ref={datasetInput} hidden type="file" accept=".json,.csv,application/json,text/csv" onChange={(event) => void importDataset(event.target.files?.[0])} /><Button size="sm" variant="outline" onClick={() => datasetInput.current?.click()}><FileUp />导入数据集</Button><Button size="sm" variant="outline" onClick={() => downloadText(result.exports.evaluationJson, `${result.skill.slug}-evals.json`, 'application/json;charset=utf-8')}><Download />导出数据集</Button><Button size="sm" variant="outline" onClick={addTest}><Plus />添加用例</Button><Button size="sm" onClick={() => void execute('evaluate')} disabled={running}><TestTube2 />运行全量评测</Button></div></header><div><article><span>用例</span><strong>{result.skill.tests.length}</strong></article><article><span>断言</span><strong>{result.skill.tests.reduce((sum, item) => sum + item.assertions.length, 0)}</strong></article><article><span>通过率</span><strong>{percent(result.evaluation.passRate)}</strong></article><article><span>无能力基线</span><strong>{percent(result.evaluation.baselinePassRate)}</strong></article></div></section>
        <section className="skillx-test-grid">{result.skill.tests.map((test, index) => { const testResult = result.evaluation.results.find((item) => item.testId === test.id); return <article key={test.id} className="skillx-surface"><header><b>{String(index + 1).padStart(2, '0')}</b><Input aria-label="用例名称" value={test.name} onChange={(event) => mutateTest(test.id, (item) => { item.name = event.target.value; })} /><span className={testResult?.passed ? 'pass' : 'warn'}>{testResult ? testResult.passed ? '通过' : '失败' : '未运行'}</span></header><div className="skillx-field skillx-test-tags"><span>标签</span><Input aria-label="用例标签" value={test.tags.join(',')} onChange={(event) => mutateTest(test.id, (item) => { item.tags = event.target.value.split(',').map((value) => value.trim()).filter(Boolean); })} /></div><label><span>输入 JSON</span><textarea className="code" defaultValue={JSON.stringify(test.input, null, 2)} onBlur={(event) => { try { const parsed = JSON.parse(event.target.value) as Record<string, unknown>; mutateTest(test.id, (item) => { item.input = parsed; }); } catch { setError(`${test.name} 的输入不是有效 JSON。`); } }} /></label><div className="skillx-assertions">{test.assertions.map((assertion) => <p key={assertion.id}><NativeSelect aria-label="断言类型" value={assertion.type} onChange={(event) => mutateTest(test.id, (item) => { const target = item.assertions.find((entry) => entry.id === assertion.id); if (target) target.type = event.target.value; })}>{assertionTypes.map(([type, label]) => <NativeSelectOption key={type} value={type}>{label}</NativeSelectOption>)}</NativeSelect><Input aria-label="输出路径" value={assertion.path} onChange={(event) => mutateTest(test.id, (item) => { const target = item.assertions.find((entry) => entry.id === assertion.id); if (target) target.path = event.target.value; })} /><Input aria-label="期望值" value={typeof assertion.value === 'string' ? assertion.value : JSON.stringify(assertion.value)} onChange={(event) => mutateTest(test.id, (item) => { const target = item.assertions.find((entry) => entry.id === assertion.id); if (target) { try { target.value = JSON.parse(event.target.value); } catch { target.value = event.target.value; } } })} /></p>)}</div><footer><button onClick={() => { const copy = structuredClone(test); copy.id = `test-${Date.now()}`; copy.name += ' 副本'; updateSkill((skill) => skill.tests.push(copy)); }}><Copy />复制</button><button className="danger" onClick={() => updateSkill((skill) => { skill.tests = skill.tests.filter((item) => item.id !== test.id); })}><Trash2 />删除</button></footer></article>; })}</section>
      </div>}
      {selectedView === 'playground' && <div className="skillx-view skillx-playground">
        <section className="skillx-surface skillx-run-input"><header><span>安全试运行</span><strong>固定步骤执行器</strong><Button size="sm" onClick={() => void execute('run')} disabled={running}><Play />执行</Button></header><textarea className="code" defaultValue={JSON.stringify(result.skill.playgroundInput, null, 2)} onBlur={(event) => { try { const parsed = JSON.parse(event.target.value) as Record<string, unknown>; updateSkill((skill) => { skill.playgroundInput = parsed; }); } catch { setError('试运行输入不是有效 JSON。'); } }} /></section>
        <section className="skillx-surface skillx-run-output"><header><span>结构化输出</span><strong>{result.latestRun?.status === 'success' ? '执行成功' : '等待执行'}</strong><small>{result.latestRun ? formatTime(result.latestRun.createdAt) : '—'}</small></header><pre>{JSON.stringify(result.latestRun?.output ?? {}, null, 2)}</pre></section>
        <section className="skillx-surface skillx-trace"><header><span>步骤追踪</span><strong>{result.latestRun?.trace.length ?? 0} 条执行证据</strong></header><div>{result.latestRun?.trace.map((trace) => <article key={`${result.latestRun?.id}-${trace.stepId}`}><b>{String(trace.order).padStart(2, '0')}</b><div><strong>{trace.name}</strong><span>{trace.type} · {trace.stepId}</span></div><em>{trace.elapsedMs.toFixed(2)} ms</em><p>{trace.message}</p></article>)}</div></section>
        <section className="skillx-surface skillx-history"><header><span>运行记录</span><strong>最近 {result.skill.runs.length} 次</strong></header><div>{result.skill.runs.map((run) => <article key={run.id}><span className={run.status === 'success' ? 'pass' : 'warn'}>{run.status === 'success' ? '成功' : '失败'}</span><strong>{formatTime(run.createdAt)}</strong><small>{run.trace.length} 步 · {run.error || '输出契约完成'}</small></article>)}</div></section>
      </div>}
      {selectedView === 'evaluation' && <div className="skillx-view skillx-evaluation">
        <section className="skillx-surface skillx-eval-summary"><header><span>评测与回归分析</span><strong>当前能力、无能力对照与历史版本</strong><Button size="sm" onClick={() => void execute('evaluate')} disabled={running}><TestTube2 />重新评测</Button></header><div>{[['用例通过率', percent(result.evaluation.passRate), `${result.evaluation.passed}/${result.evaluation.total}`], ['断言通过率', percent(result.evaluation.assertionRate), `${result.evaluation.assertionPassed}/${result.evaluation.assertionTotal}`], ['对照组提升', `+${percent(result.evaluation.uplift)}`, `基线 ${percent(result.evaluation.baselinePassRate)}`], ['步骤覆盖率', percent(result.evaluation.stepCoverage), '实际经过步骤'], ['P50', `${result.evaluation.p50Ms.toFixed(2)} ms`, '中位耗时'], ['P95', `${result.evaluation.p95Ms.toFixed(2)} ms`, '性能漂移基线']].map(([label, value, note]) => <article key={label}><span>{label}</span><strong>{value}</strong><small>{note}</small></article>)}</div></section>
        <section className="skillx-surface skillx-eval-table"><header><span>逐用例证据</span><strong>断言实际值与对照结果</strong></header><div><table><thead><tr><th>用例</th><th>标签</th><th>当前能力</th><th>无能力基线</th><th>断言</th><th>耗时</th></tr></thead><tbody>{result.evaluation.results.map((item) => { const baseline = result.evaluation.baselines.find((entry) => entry.testId === item.testId); return <tr key={item.testId}><td><strong>{item.name}</strong>{item.error && <small>{item.error}</small>}</td><td>{item.tags.map((tag) => <em key={tag}>{tagLabels[tag] ?? tag}</em>)}</td><td><b className={item.passed ? 'pass' : 'warn'}>{item.passed ? '通过' : '失败'}</b></td><td><b className={baseline?.passed ? 'pass' : 'muted'}>{baseline?.passed ? '通过' : '未通过'}</b></td><td>{item.assertions.map((assertion) => <small key={assertion.id} className={assertion.pass ? 'pass' : 'warn'}>{assertion.pass ? '✓' : '×'} {assertionTypeLabel(assertion.type)} · {assertion.path || '$'}</small>)}</td><td>{item.elapsedMs.toFixed(2)} ms</td></tr>; })}</tbody></table></div></section>
        <section className="skillx-surface skillx-regression"><header><span>历史版本对比</span><strong>{selectedRelease ? `当前草案与 v${selectedRelease.version}` : '尚无发布基线'}</strong></header>{selectedRelease ? <div><article className="pass"><span>改善</span><strong>0</strong><small>无新增改善项</small></article><article><span>保持</span><strong>{result.evaluation.total}</strong><small>全部用例状态稳定</small></article><article className="pass"><span>回归</span><strong>0</strong><small>没有用例退化</small></article></div> : <p>生成第一个发布版本后，将显示逐用例回归、改善和通过率变化。</p>}</section>
      </div>}
      {selectedView === 'security' && <div className="skillx-view skillx-security">
        <section className="skillx-surface skillx-scan"><header><span>静态供应链扫描</span><strong>路径、密钥、命令、网络与提示注入</strong><Button size="sm" onClick={() => void execute('security-scan')} disabled={running}><ScanSearch />重新扫描</Button></header><div className="skillx-risk-counts"><article><strong>{result.security.counts.critical ?? 0}</strong><span>严重</span></article><article><strong>{result.security.counts.high ?? 0}</strong><span>高</span></article><article><strong>{result.security.counts.medium ?? 0}</strong><span>中</span></article><article><strong>{result.skill.files.length}</strong><span>扫描文件</span></article></div><div className="skillx-findings">{result.security.findings.length ? result.security.findings.map((item, index) => <p key={`${item.code}-${index}`} className={item.severity}><b>{item.severity}</b><span>{item.message}</span><code>{item.file}</code></p>) : <p className="empty"><CheckCircle2 />未发现阻断发布的静态风险</p>}</div></section>
        <section className="skillx-surface skillx-provenance"><header><span>来源与责任链</span><strong>事实记录与人工核验</strong></header><div className="skillx-form"><div className="skillx-field wide"><span>来源</span><Input aria-label="来源" value={result.skill.provenance.source} onChange={(event) => updateSkill((skill) => { skill.provenance.source = event.target.value; })} /></div><div className="skillx-field"><span>维护者</span><Input aria-label="维护者" value={result.skill.provenance.maintainer} onChange={(event) => updateSkill((skill) => { skill.provenance.maintainer = event.target.value; })} /></div><div className="skillx-field"><span>上游项目或仓库</span><Input aria-label="上游项目或仓库" value={result.skill.provenance.upstream} onChange={(event) => updateSkill((skill) => { skill.provenance.upstream = event.target.value; })} /></div><label className="wide"><span>许可证审查</span><textarea value={result.skill.provenance.licenseReview} onChange={(event) => updateSkill((skill) => { skill.provenance.licenseReview = event.target.value; })} /></label><div className="skillx-field"><span>签名状态</span><NativeSelect aria-label="签名状态" value={result.skill.provenance.signatureStatus} onChange={(event) => updateSkill((skill) => { skill.provenance.signatureStatus = event.target.value; })}><NativeSelectOption value="未签名">未签名</NativeSelectOption><NativeSelectOption value="内部校验和">内部校验和</NativeSelectOption><NativeSelectOption value="外部签名已核验">外部签名已核验</NativeSelectOption></NativeSelect></div><div className="skillx-field"><span>最近人工复核日期</span><Input aria-label="最近人工复核日期" type="date" value={result.skill.provenance.reviewedAt} onChange={(event) => updateSkill((skill) => { skill.provenance.reviewedAt = event.target.value; })} /></div></div></section>
        <section className="skillx-surface skillx-boundaries">{[['01', '导入隔离', 'ZIP 中的脚本只按 UTF-8 文本读取，不会执行。'], ['02', '最小权限', '允许工具范围过宽会阻断发布。'], ['03', '发布校验', '导出包包含 SHA-256 清单与门禁结果。'], ['04', '人工责任', '高风险输出由复核步骤和责任记录约束。']].map(([number, title, copy]) => <article key={number}><b>{number}</b><strong>{title}</strong><span>{copy}</span></article>)}</section>
      </div>}
      {selectedView === 'releases' && <div className="skillx-view skillx-releases">
        <section className="skillx-surface skillx-release-form"><header><span>语义版本发布</span><strong>{result.releaseGate.pass ? '门禁已通过' : '发布被阻断'}</strong><em className={result.releaseGate.pass ? 'pass' : 'warn'}>{result.releaseGate.pass ? '可发布' : `${result.releaseGate.blockers.length} 项阻断`}</em></header><div><div className="skillx-field"><span>升级级别</span><NativeSelect aria-label="升级级别" value={releaseLevel} onChange={(event) => setReleaseLevel(event.target.value)}><NativeSelectOption value="patch">修订版本</NativeSelectOption><NativeSelectOption value="minor">次版本</NativeSelectOption><NativeSelectOption value="major">主版本</NativeSelectOption></NativeSelect></div><div className="skillx-field"><span>发布通道</span><NativeSelect aria-label="发布通道" value={releaseChannel} onChange={(event) => setReleaseChannel(event.target.value)}><NativeSelectOption value="canary">灰度通道</NativeSelectOption><NativeSelectOption value="stable">稳定通道</NativeSelectOption></NativeSelect></div><label className="wide"><span>发布说明</span><textarea value={result.skill.releaseNotes} onChange={(event) => updateSkill((skill) => { skill.releaseNotes = event.target.value; })} /></label><Button onClick={() => void execute('publish', { level: releaseLevel, channel: releaseChannel })} disabled={running || !result.releaseGate.pass}><Archive />执行门禁并发布</Button></div>{result.releaseGate.blockers.map((item) => <p key={item}><CircleAlert />{item}</p>)}</section>
        <section className="skillx-surface skillx-release-list"><header><span>版本档案</span><strong>{result.skill.releases.length} 个不可变快照</strong></header><div>{result.skill.releases.length ? result.skill.releases.map((release) => <button key={release.id} className={selectedRelease?.id === release.id ? 'active' : ''} onClick={() => setSelectedReleaseId(release.id)}><span>{release.channel === 'stable' ? '稳定' : release.channel === 'canary' ? '灰度' : '检查点'}</span><strong>v{release.version}</strong><small>{formatTime(release.createdAt)} · 通过率 {percent(release.evaluation.passRate)}</small><em>{release.notes || '无发布说明'}</em></button>) : <p>尚无发布版本。当前基准已经通过门禁，可以生成首个快照。</p>}</div></section>
        <section className="skillx-surface skillx-release-diff"><header><span>差异与回滚</span><strong>{selectedRelease ? `当前草案与 v${selectedRelease.version}` : '选择发布版本'}</strong>{selectedRelease && <Button size="sm" variant="outline" onClick={restoreRelease}><RotateCcw />安全回滚</Button>}</header>{selectedRelease ? <div><p><b>版本</b><span>{selectedRelease.version}</span><strong>→</strong><span>{result.skill.version}</span></p><p><b>通道</b><span>{selectedRelease.channel}</span><strong>→</strong><span>{result.skill.channel}</span></p><p><b>评测</b><span>{percent(selectedRelease.evaluation.passRate)}</span><strong>→</strong><span>{percent(result.evaluation.passRate)}</span></p></div> : <p>发布后可查看关键字段差异，并在保留当前运行与评测记录的前提下恢复内容。</p>}</section>
        <section className="skillx-surface skillx-exports"><header><span>完整交付包</span><strong>规范、评测、清单、注册表与校验和</strong></header><div><button onClick={() => downloadText(result.exports.skillMarkdown, 'SKILL.md', 'text/markdown;charset=utf-8')}><FileCode2 /><strong>Skill 规范</strong><small>Markdown</small></button><button onClick={() => downloadText(result.exports.evaluationJson, 'evals.json', 'application/json;charset=utf-8')}><FileJson /><strong>测试与评测</strong><small>JSON</small></button><button onClick={() => downloadText(result.exports.benchmarkMarkdown, 'BENCHMARK.md', 'text/markdown;charset=utf-8')}><Download /><strong>基准报告</strong><small>Markdown</small></button><button onClick={() => downloadText(result.exports.manifestJson, 'manifest.json', 'application/json;charset=utf-8')}><FileJson /><strong>包清单</strong><small>JSON</small></button><button onClick={() => downloadText(result.exports.registryJson, 'skill-registry.json', 'application/json;charset=utf-8')}><Boxes /><strong>注册表</strong><small>JSON</small></button><button className="primary" disabled={!result.exports.packageBase64} onClick={() => result.exports.packageBase64 && downloadBase64(result.exports.packageBase64, `${result.skill.slug}-${result.skill.version}.zip`)}><FileArchive /><strong>完整 Skill 包</strong><small>{result.exports.packageBase64 ? 'ZIP + SHA-256' : '执行完整流程后生成'}</small></button></div></section>
        <section className="skillx-surface skillx-runtime"><header><span>运行与信任边界</span><strong>真实连接状态</strong></header><dl><div><dt>Python 计算</dt><dd className="pass">已连接</dd><small>{result.runtime.compute}</small></div><div><dt>Go 项目与审计</dt><dd className="pass">已连接</dd><small>{result.runtime.orchestration}</small></div><div><dt>任意代码执行</dt><dd className="pass">已关闭</dd><small>只允许固定安全步骤</small></div><div><dt>外部网络访问</dt><dd className="pass">已关闭</dd><small>运行器没有网络步骤</small></div><div><dt>包签名核验</dt><dd>待配置</dd><small>当前提供 SHA-256 完整性清单</small></div></dl></section>
      </div>}
    </main>
  </section>;
}
